<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { Search, ShieldCheck, ChevronLeft, ChevronRight } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import AppModal from '../components/AppModal.vue'
import { api, query, type Page } from '../lib/api'
import { formatTime } from '../lib/format'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
interface Audit { id: string; actorId: string; actorName: string; action: string; entityId: string; message: string; requestId: string; createdAt: string }
const workspace = useWorkspace(), { loading, error, run } = useAsync(), items = ref<Audit[]>([]), selected = ref<Audit>(), page = ref(0), total = ref(0), q = ref(''), size = 20
const pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
const actionLabel = (action: string) => ({ ENROLL: '选课', WITHDRAW: '退课', SWAP: '换课', WAITLIST_JOIN: '申请候补', WAITLIST_CANCEL: '取消候补', PROMOTE: '候补递补', GRADE_SAVE: '保存成绩草稿', GRADE_PUBLISH: '正式发布成绩', GRADE_REOPEN: '开放成绩更正', GRADES_DRAFT: '保存成绩草稿', GRADES_PUBLISH: '正式发布成绩', GRADES_REOPEN: '开放成绩更正', CREATE: '新增教学记录', UPDATE: '修改教学记录', DELETE: '删除教学记录', LOGIN: '账户登录' }[action] || action)
async function load(reset = false) { if (reset) page.value = 0; await run(() => api<Page<Audit>>('/admin/audit' + query({ q: q.value.trim(), termId: workspace.termId, page: page.value, size })), result => { items.value = result.items; total.value = result.total }) }
function paginate(delta: number) { page.value += delta; void load() }
watch(() => workspace.termId, () => load(true), { immediate: true })
</script>
<template><PageHeading eyebrow="EVERY IMPORTANT CHANGE, ACCOUNTED FOR" title="操作记录" description="选课、成绩与教学安排的重要变化，都有清晰的来处。"><select v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><button class="button button-secondary" :disabled="loading" @click="load()"><ShieldCheck :size="14"/>刷新记录</button></PageHeading><section class="card"><div class="card-header"><div><h2>教学操作审计</h2><p>共 {{ total }} 条记录 · 只读追溯，不可从页面修改</p></div><form class="search-field" @submit.prevent="load(true)"><Search :size="14"/><input v-model="q" placeholder="搜索操作、对象或说明" aria-label="搜索操作记录"><button type="submit" class="icon-button" aria-label="执行搜索" style="width:20px;height:20px"><ChevronRight :size="14"/></button></form></div><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load()"/><StatePanel v-else-if="!items.length" title="暂时没有匹配的操作记录" description="尝试调整关键词；新的教学操作会自动记录在这里。"/><div v-else class="table-wrap"><table><caption class="sr-only">真实教学操作记录</caption><thead><tr><th>发生时间</th><th>操作人</th><th>操作类型</th><th>关联对象</th><th>操作说明</th><th>详情</th></tr></thead><tbody><tr v-for="item in items" :key="item.id"><td>{{ formatTime(item.createdAt) }}</td><td><strong>{{ item.actorName }}</strong></td><td><span class="tag tag-neutral">{{ actionLabel(item.action) }}</span></td><td class="mono">{{ item.entityId }}</td><td style="max-width:280px;overflow-wrap:anywhere">{{ item.message }}</td><td><button class="text-button" @click="selected = item">查看详情</button></td></tr></tbody></table></div><div v-if="total" class="card-footer"><span>第 {{ page + 1 }} / {{ pages }} 页</span><div class="pagination"><button aria-label="上一页" :disabled="page === 0 || loading" @click="paginate(-1)"><ChevronLeft :size="14"/></button><button aria-label="下一页" :disabled="page + 1 >= pages || loading" @click="paginate(1)"><ChevronRight :size="14"/></button></div></div></section><AppModal :open="!!selected" title="操作记录详情" @close="selected = undefined"><dl v-if="selected" class="detail-grid"><div><dt>操作类型</dt><dd>{{ actionLabel(selected.action) }}</dd></div><div><dt>操作人</dt><dd>{{ selected.actorName }}</dd></div><div><dt>关联对象</dt><dd class="mono overflow-anywhere">{{ selected.entityId }}</dd></div><div><dt>发生时间</dt><dd>{{ formatTime(selected.createdAt) }}</dd></div><div class="field-full"><dt>操作说明</dt><dd class="overflow-anywhere">{{ selected.message }}</dd></div><div class="field-full"><dt>请求追踪编号</dt><dd class="mono overflow-anywhere">{{ selected.requestId }}</dd></div></dl><template #footer><button class="button button-secondary" @click="selected = undefined">关闭</button></template></AppModal></template>
